/* ===== operacao.css ===== */
/* Operação pós-Home — visual mobile-first do protótipo novo */
.operational {
  min-height: 100dvh;
  background: var(--page);
  padding-bottom: 78px;
}
.app-header {
  position: sticky;
  top: 0;
  z-index: 12;
  min-height: 62px;
  display: grid;
  grid-template-columns: 42px 1fr auto;
  gap: 10px;
  align-items: center;
  padding: 8px 14px;
  background: var(--primary);
  color: #fff;
  box-shadow: 0 4px 14px rgba(16,35,63,.18);
}
.app-menu-button {
  width: 40px;
  height: 40px;
  display: grid;
  place-content: center;
  gap: 4px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #fff;
  cursor: pointer;
}
.app-menu-button span {
  width: 20px;
  height: 2px;
  border-radius: 9px;
  background: currentColor;
}
.app-brand {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 16px;
  letter-spacing: -.02em;
}
.app-brand img {
  width: 27px;
  height: 27px;
  object-fit: contain;
  filter: brightness(0) invert(1);
}
.app-role {
  font-size: 10px;
  font-weight: 800;
  opacity: .8;
  text-transform: uppercase;
  letter-spacing: .06em;
}
.app-titlebar {
  padding: 10px 18px;
  border-bottom: 1px solid var(--line);
  background: #fff;
  color: var(--primary);
  font-size: 13px;
}
.op-shell {
  width: min(100%, 720px);
  margin: 0 auto;
  padding: 22px 16px 36px;
}
.op-shell > .eyebrow {
