regras.b1.02:
.app-header {
  min-height: 64px;
  display: grid;
  grid-template-columns: 42px minmax(0,1fr) 42px;
  gap: 10px;
  align-items: center;
  padding: 8px 14px;
  background: var(--primary);
  color: #fff;
  box-shadow: 0 4px 14px rgba(16,35,63,.18);
}
.app-menu-button,
.app-notifications {
  width: 40px;
  height: 40px;
  display: grid;
  place-content: center;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #fff;
  cursor: pointer;
}
.app-menu-button { gap: 4px; }
.app-menu-button span {
  width: 20px;
  height: 2px;
  border-radius: 9px;
  background: currentColor;
}
.app-brand {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 9px;
}
.app-brand img {
  width: 28px;
  height: 28px;
  object-fit: contain;
  filter: brightness(0) invert(1);
}
.app-brand-copy { min-width: 0; }
.app-brand-copy strong,
.app-brand-copy small { display:block; }
.app-brand-copy strong {
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  font-size:16px;
  letter-spacing:-.02em;
}
.app-brand-copy small {
  margin-top:1px;
  font-size:9px;
  font-weight:800;
  letter-spacing:.08em;
  text-transform:uppercase;
  opacity:.72;
}
.app-notifications {
  position: relative;
  justify-self: end;
}
.app-notifications svg {
  width: 22px;
  height: 22px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.app-notifications-badge {
  position:absolute;
  top:4px;
  right:2px;
  min-width:16px;
  height:16px;
  padding:0 4px;
  display:grid;
  place-items:center;
  border:2px solid var(--primary);
  border-radius:999px;
  background:#ef4444;
  color:#fff;
