.admin-ui .detail-grid{display:grid;gap:10px}.admin-ui .detail-row{display:grid;grid-template-columns:minmax(120px,.7fr) 1.3fr;gap:12px;padding:10px 0;border-bottom:1px solid #edf0f4;font-size:12px}.admin-ui .detail-row:last-child{border-bottom:0}.admin-ui .detail-row span{color:var(--muted)}.admin-ui .detail-row strong{color:var(--primary)}
