}
.login-flow__subcopy {
  margin: 0 0 18px;
  color: #667085;
  font-size: 14px;
  line-height: 1.5;
}
.login-flow .role-choice {
  margin-bottom: 12px;
  padding: 14px;
  border: 1px solid #dbe3ee;
  border-radius: 14px;
  background: #fff;
  box-shadow: 0 4px 12px rgba(15,23,42,.035);
}
.login-flow .role-choice-head {
  display: grid;
  grid-template-columns: 44px 1fr;
  gap: 12px;
  align-items: center;
  margin-bottom: 12px;
}
.login-flow .mini-icon {
  display: grid;
  width: 44px;
  height: 44px;
  place-items: center;
  border-radius: 13px;
  background: #e7f0ff;
  color: #10233f;
  font-weight: 900;
}
.login-flow .mini-icon.gold { background: #fff4db; color: #b88932; }
.login-flow .mini-icon.ok { background: #def7ec; color: #0f8f62; }
.login-flow .title {
  margin-bottom: 4px;
  color: #172033;
  font-size: 15px;
  font-weight: 800;
}
.login-flow .muted {
  color: #667085;
  font-size: 12px;
  line-height: 1.35;
  font-weight: 600;
}
.login-flow .role-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}
.login-flow .role-actions.single {
  grid-template-columns: 1fr;
}
.login-flow .role-actions button {
  min-height: 38px;
  border: 1px solid #10233f;
  border-radius: 10px;
  padding: 8px 10px;
  background: #10233f;
  color: #fff;
  font: inherit;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: .03em;
  cursor: pointer;
}
.login-flow .role-actions button + button {
  background: transparent;
  color: #10233f;
}
@media (min-width: 700px) {
  .login-flow__content {
    width: min(calc(100% - 48px), var(--login-flow-content-max));
    padding: 54px 0 112px;
  }
}
.login-flow__note {
  margin-top: 16px;
  padding: 12px 13px;
  border: 1px dashed #c8d3df;
  border-radius: 12px;
  color: #667085;
  font-size: 11px;
  line-height: 1.45;
}



