}
.secondary {
  width: 100%;
  min-height: 50px;
  margin-top: 9px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fff;
  color: var(--primary);
  font-weight: 800;
}
.signup {
  margin: 20px 0 0;
  color: var(--muted);
  text-align: center;
  font-size: 13px;
}
.signup a {
  color: var(--primary);
  font-weight: 800;
}
.status {
  min-height: 20px;
  margin: 12px 0 0;
  color: var(--primary);
  text-align: center;
  font-size: 12px;
  font-weight: 700;
}
@media (min-width: 700px) {
  .welcome {
    min-height: 100dvh;
    padding: 34px;
    background: #e9eff6;
  }
  .welcome__layout {
    width: min(1080px, 100%);
    min-height: min(680px, calc(100dvh - 68px));
    margin: auto;
    display: grid;
    grid-template-columns: 1.08fr 0.92fr;
    overflow: hidden;
    border: 1px solid var(--line);
    border-radius: 20px;
    background: #fff;
    box-shadow: 0 12px 36px rgba(16, 35, 63, 0.14);
  }
  .welcome__image,
  .welcome__image img {
