  padding: 0 7px;
  border-radius: 999px;
}
.screen-meta {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}
.screen-meta strong {
  font-size: 14px;
}
.screen-meta small {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

/* ===== Cadastro comum — dados pessoais ===== */
.registration {
  min-height: 100dvh;
  background: var(--page);
}
.registration__shell {
  width: min(100%, 620px);
  margin: 0 auto;
  padding: 24px 18px 48px;
}
.registration__intro {
  margin: 2px 2px 18px;
}
.registration__intro h1,
.registration--success h1 {
  margin: 0;
  color: var(--primary);
  font-size: clamp(25px, 7vw, 34px);
  line-height: 1.12;
  letter-spacing: -0.025em;
}
.registration__intro > p:not(.eyebrow),
.registration--success > .registration__shell > p:not(.eyebrow):not(.form-status) {
  margin: 10px 0 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.58;
}
.progress {
  height: 5px;
  margin: 0 2px 18px;
  overflow: hidden;
  border-radius: 999px;
  background: #dce4ed;
}
.progress span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--gold);
}
.form-card {
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--surface);
}
.form-card .field:last-of-type {
  margin-bottom: 0;
}
.form-card .field input,
.form-card .select-field select {
  background: #fff;
  color: var(--text);
}
.select-field {
  position: relative;
  margin-bottom: 14px;
}
.select-field label {
  position: absolute;
  z-index: 1;
  top: 8px;
  left: 14px;
  color: var(--primary);
  font-size: 10px;
  font-weight: 800;
  pointer-events: none;
}
.select-field select {
  width: 100%;
  min-height: 57px;
  appearance: auto;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 22px 40px 9px 14px;
  outline: 0;
  cursor: pointer;
}
.field-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0;
}
.choice-group {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 0;
  border: 0;
}
.choice-group legend {
  margin-bottom: 10px;
  color: var(--primary);
  font-size: 12px;
  font-weight: 800;
}
.choice-card {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 12px;
  align-items: center;
  min-height: 78px;
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 14px;
  cursor: pointer;
  transition: border-color .18s ease, background .18s ease, box-shadow .18s ease;
}
.choice-card:has(input:checked) {
  border-color: var(--primary-soft);
  background: #f3f7fc;
  box-shadow: inset 0 0 0 1px rgba(23, 60, 107, .16);
}
.choice-card input {
  width: 18px;
  height: 18px;
  accent-color: var(--primary);
}
.choice-card span {
  min-width: 0;
}
.choice-card strong,
.choice-card small {
  display: block;
}
.choice-card strong {
  color: var(--primary);
  font-size: 14px;
}
.choice-card small {
  margin-top: 4px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}
.choice-card b {
  color: var(--primary-soft);
  font-size: 24px;
  font-weight: 500;
}
.form-note {
  display: flex;
  gap: 8px;
  margin: 16px 0 0;
  border-radius: 12px;
  padding: 12px 13px;
  background: #f3f6fa;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}
.form-note strong {
  flex: 0 0 auto;
  color: var(--primary);
}
.form-actions {
  display: grid;
  grid-template-columns: minmax(96px, .7fr) 1.3fr;
  gap: 10px;
  margin-top: 20px;
}
.form-actions.single {
  grid-template-columns: 1fr;
}
.secondary-action {
  min-height: 54px;
  border: 1px solid var(--line);
  border-radius: 13px;
  padding: 14px 16px;
  background: #fff;
  color: var(--primary);
  font-weight: 800;
  cursor: pointer;
}
.form-status {
  min-height: 18px;
  margin: 10px 0 0;
  color: #9b2c2c;
  text-align: center;
  font-size: 11px;
  font-weight: 700;
}
.upload-field {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px 12px;
  align-items: center;
  margin: 4px 0 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 13px 14px;
  cursor: pointer;
}
.upload-field input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.upload-field strong,
.upload-field small,
.upload-field em {
  display: block;
}
.upload-field strong {
  color: var(--primary);
  font-size: 13px;
}
.upload-field small,
.upload-field em {
  color: var(--muted);
  font-size: 10px;
  font-style: normal;
}
.upload-field em {
  grid-column: 1 / -1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.upload-button {
  border-radius: 9px;
  padding: 9px 10px;
  background: #eef3f8;
  color: var(--primary);
  font-size: 11px;
  font-weight: 800;
}
.legal-links {
  display: grid;
  gap: 8px;
  margin-bottom: 14px;
}
.legal-link {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 13px 14px;
  background: #fff;
  color: var(--primary);
  text-align: left;
  cursor: pointer;
}
.legal-link strong,
.legal-link small {
  display: block;
}
.legal-link small {
  margin-top: 3px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 500;
}
.legal-link b {
  font-size: 22px;
  font-weight: 500;
}
.check-row {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 10px;
  align-items: start;
  color: var(--text);
  font-size: 12px;
  line-height: 1.5;
  cursor: pointer;
}
.check-row input {
  width: 18px;
  height: 18px;
  margin: 1px 0 0;
  accent-color: var(--primary);
}
.link-button {
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--primary);
  font-weight: 800;
  cursor: pointer;
}
.review-section + .review-section {
  margin-top: 18px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
}
.review-section__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}
.review-section__head strong {
  color: var(--primary);
  font-size: 14px;
}
.review-section__head button {
  border: 0;
  padding: 5px 0;
  background: transparent;
  color: var(--primary-soft);
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}
.review-section dl {
  margin: 0;
}
.review-section dl > div {
  display: grid;
  grid-template-columns: minmax(92px, .55fr) 1.45fr;
  gap: 10px;
  padding: 8px 0;
}
.review-section dt {
  color: var(--muted);
  font-size: 11px;
}
.review-section dd {
  margin: 0;
  overflow-wrap: anywhere;
  color: var(--text);
  font-size: 12px;
  font-weight: 700;
}
.registration--success .success-shell {
  min-height: calc(100dvh - 64px);
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-top: 36px;
  padding-bottom: 60px;
  text-align: center;
}
.success-mark {
  display: grid;
  width: 74px;
  height: 74px;
  margin: 0 auto 18px;
  place-items: center;
  border-radius: 50%;
  background: var(--primary);
  color: #fff;
  font-size: 34px;
  font-weight: 800;
  box-shadow: 0 12px 28px rgba(16, 35, 63, .18);
}
.registration--success .form-note {
  margin: 24px 0 18px;
  text-align: left;
}
.text-action {
  margin-top: 12px;
  border: 0;
  background: transparent;
  color: var(--primary);
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}
@media (min-width: 520px) {
  .field-grid {
    grid-template-columns: 1fr 1fr;
    gap: 12px;
  }
}
@media (min-width: 700px) {
  .registration__shell {
    padding-top: 38px;
    padding-bottom: 64px;
  }
  .form-card {
    padding: 26px;
    box-shadow: 0 12px 36px rgba(16, 35, 63, 0.10);
  }
}


