  color: var(--primary);
  text-align: center;
  font-size: 12px;
  font-weight: 700;
}
@media (min-width: 700px) {
  .welcome {
    min-height: 100dvh;
    padding: 34px;
    background: #e9eff6;
  }
  .welcome__layout {
    width: min(1080px, 100%);
    min-height: min(680px, calc(100dvh - 68px));
    margin: auto;
    display: grid;
    grid-template-columns: 1.08fr 0.92fr;
    overflow: hidden;
    border: 1px solid var(--line);
    border-radius: 20px;
    background: #fff;
    box-shadow: 0 12px 36px rgba(16, 35, 63, 0.14);
