}
.choice-card small {
  margin-top: 4px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}
.choice-card b {
  color: var(--primary-soft);
  font-size: 24px;
  font-weight: 500;
}
.form-note {
