}
.welcome {
  display: flex;
  flex-direction: column;
  background: var(--surface);
}
.welcome__image {
  min-height: 38dvh;
  overflow: hidden;
  background: #dce7f4;
}
.welcome__image img {
  display: block;
  width: 100%;
  min-height: 38dvh;
  height: 100%;
