.app-header {
  min-height: 64px;
  display: grid;
  grid-template-columns: 42px minmax(0,1fr) 42px;
  gap: 10px;
  align-items: center;
  padding: 8px 14px;
  background: var(--primary);
  color: #fff;
  box-shadow: 0 4px 14px rgba(16,35,63,.18);
}
.app-menu-button,.app-notifications {
  width:40px;height:40px;border:0;border-radius:10px;background:transparent;color:#fff;cursor:pointer;
}
.app-menu-button { display:grid;place-content:center;gap:4px; }
.app-menu-button span { width:20px;height:2px;border-radius:99px;background:currentColor; }
.app-brand { min-width:0;display:flex;align-items:center;gap:9px; }
.app-brand img { width:28px;height:28px;object-fit:contain;filter:brightness(0) invert(1); }
.app-brand-copy strong,.app-brand-copy small { display:block; }
