.app-notifications-badge {
  position:absolute;top:4px;right:2px;min-width:16px;height:16px;padding:0 4px;display:grid;place-items:center;
  border:2px solid var(--primary);border-radius:999px;background:#d92d20;color:#fff;font-size:9px;font-weight:900;
}

regras.b1.05:
.plans-shell {
  width:min(100%,980px);
  margin:0 auto;
  padding:26px 16px 42px;
  color:var(--text);
}
.plans-heading h1 { margin:0;color:var(--primary);font-size:26px;letter-spacing:-.03em; }
.plans-heading p { max-width:680px;margin:7px 0 0;color:var(--muted);font-size:13px;line-height:1.55; }

.current-summary {
  margin:18px 0;
  padding:12px 14px;
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:12px;
  border:1px solid #ead7a8;
  border-radius:14px;
  background:#fffaf0;
}
.current-summary strong { display:block;color:#6d4d10;font-size:13px; }
.current-summary span { display:block;margin-top:3px;color:#806a3b;font-size:11px; }
.current-pill {
  flex:none!important;margin:0!important;padding:5px 10px;border-radius:999px;background:#fff1c7;
  color:#77510b!important;font-size:10px!important;font-weight:900;text-transform:uppercase;letter-spacing:.04em;
}

.plans-grid { display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px; }
.plan-card {
  min-width:0;display:flex;flex-direction:column;padding:18px;border:1px solid var(--line);
  border-radius:18px;background:#fff;box-shadow:0 3px 12px rgba(16,35,63,.04);
}
.plan-card.current { border:1.5px solid #d6b76e;background:#fffdf8;box-shadow:0 8px 22px rgba(184,137,50,.10); }
.plan-badge {
  align-self:flex-start;min-height:24px;display:inline-flex;align-items:center;padding:3px 9px;border-radius:999px;
  background:#f2f4f7;color:#475467;font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.045em;
}
.current .plan-badge { background:#fff2c8;color:#7b560d; }
.plan-card h2 { margin:14px 0 4px;color:var(--primary);font-size:20px;letter-spacing:-.02em; }
.plan-description { min-height:38px;margin:0;color:var(--muted);font-size:12px;line-height:1.5; }
.price { margin:18px 0 0;color:var(--primary);font-size:27px;font-weight:900;letter-spacing:-.03em; }
.price small { color:var(--muted);font-size:11px;font-weight:700;letter-spacing:0; }

.course-access {
  margin:14px 0 0;padding:11px 12px;display:grid;grid-template-columns:34px minmax(0,1fr);gap:10px;align-items:center;
  border:1px solid #dbe3ee;border-radius:12px;background:#f8fafc;
}
.course-icon { width:34px;height:34px;display:grid;place-items:center;border-radius:9px;background:#e8eef6;color:var(--primary);font-size:12px;font-weight:900; }
.course-access strong { display:block;color:var(--primary);font-size:11px; }
.course-access span { display:block;margin-top:2px;color:var(--muted);font-size:10px;line-height:1.4; }
.course-none { background:#fafafa; }
.course-none .course-icon { background:#f2f4f7;color:#98a2b3; }

.features { display:grid;gap:9px;margin:16px 0 20px;padding-top:15px;border-top:1px solid #edf1f5; }
.feature { display:grid;grid-template-columns:18px minmax(0,1fr);gap:8px;align-items:start;color:#344054;font-size:12px;line-height:1.45; }
.feature b {
  width:18px;height:18px;display:grid;place-items:center;border-radius:50%;background:#e9f7ef;color:#08744e;font-size:11px;
}
.plan-primary {
  width:100%;min-height:44px;margin-top:auto;padding:10px 14px;border:0;border-radius:11px;background:var(--primary);
  color:#fff;font-size:12px;font-weight:900;cursor:pointer;
}
.current-button { background:#7c5a18; }
.renewal { margin-top:9px;color:var(--muted);font-size:10px;text-align:center; }
.commercial-note {
  margin-top:18px;padding:12px 14px;display:grid;gap:4px;border:1px solid var(--line);
  border-radius:13px;background:#f8fafc;color:var(--muted);font-size:10px;line-height:1.5;
}
.commercial-note strong { color:var(--primary);font-size:11px; }
.op-toast {
  position:fixed;left:50%;bottom:18px;transform:translateX(-50%);z-index:100;
  display:none;max-width:min(92vw,460px);padding:10px 14px;border-radius:10px;background:#172033;color:#fff;font-size:11px;
}
.op-toast.show { display:block; }

@media(max-width:700px) {
  .plans-grid { grid-template-columns:1fr; }
  .current-summary { align-items:flex-start;flex-direction:column; }
  .plans-shell { padding-left:13px;padding-right:13px; }
  .plan-description { min-height:0; }
}

regras.b1.06:
.prototype-drawer {
  position: fixed;
  z-index: 40;
  inset: 0;
  display: none;
}

.prototype-drawer.open { display: block; }

.drawer-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  border: 0;
  background: rgba(7, 16, 30, .60);
}

.drawer-panel {
  position: absolute;
  inset: 0 auto 0 0;
  width: min(80vw, 360px);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background: #3b4a7d;
  color: #fff;
  box-shadow: 12px 0 30px rgba(0, 0, 0, .32);
}

.drawer-top {
  flex: 0 0 auto;
  min-height: 106px;
  padding: 30px 22px 20px;
  display: flex;
  align-items: center;
}

.drawer-identity {
  min-width: 0;
  display: flex;
  gap: 14px;
  align-items: center;
}

.drawer-avatar {
  flex: 0 0 56px;
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  border: 2px solid rgba(255, 255, 255, .20);
  border-radius: 50%;
  background: #dbeafe;
  color: #1e3a8a;
  font-size: 20px;
  font-weight: 800;
}

.drawer-profile { min-width: 0; }
.drawer-profile strong,
.drawer-profile small { display: block; }
.drawer-profile strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 16px;
  font-weight: 600;
}
.drawer-profile small {
  margin-top: 2px;
  color: #bfdbfe;
  font-size: 11px;
  font-weight: 400;
  text-transform: lowercase;
}

.drawer-online {
  flex: 0 0 auto;
  width: calc(100% - 44px);
  margin: 0 22px 10px;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  align-items: center;
  border: 1px solid rgba(255, 255, 255, .18);
  border-radius: 10px;
  padding: 10px 12px;
  background: rgba(255, 255, 255, .08);
  color: #fff;
  text-align: left;
  cursor: pointer;
}
.drawer-online-copy strong,
.drawer-online-copy small { display: block; }
.drawer-online-copy strong { font-size: 13px; }
.drawer-online-copy small { margin-top: 2px; color: #bfdbfe; font-size: 10px; }
.online-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #4ade80;
  box-shadow: 0 0 0 4px rgba(74, 222, 128, .14);
}
.drawer-online.is-offline .online-dot { background: #98a2b3; box-shadow: none; }
.online-switch { position: relative; width: 38px; height: 22px; border-radius: 999px; background: #22c55e; }
.online-switch b { position: absolute; top: 3px; right: 3px; width: 16px; height: 16px; border-radius: 50%; background: #fff; }
.drawer-online.is-offline .online-switch { background: #64748b; }
.drawer-online.is-offline .online-switch b { right: 19px; }

.drawer-nav {
  flex: 1 1 auto;
  min-height: 0;
  display: block;
  margin: 0;
  padding: 0 0 8px;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, .35) transparent;
}
.drawer-nav::-webkit-scrollbar { width: 5px; }
.drawer-nav::-webkit-scrollbar-thumb { border-radius: 999px; background: rgba(255, 255, 255, .35); }

.drawer-nav button {
  width: 100%;
  min-height: 51px;
  padding: 14px 22px;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, .10);
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 15px;
  align-items: center;
  text-align: left;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
}
.drawer-nav button:hover { background: rgba(255, 255, 255, .08); }
.drawer-icon { flex: 0 0 20px; width: 20px; height: 20px; color: #aebee5; }

.drawer-footer {
  flex: 0 0 auto;
  margin-top: 0;
  padding: 16px 22px 30px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  background: rgba(0, 0, 0, .10);
}
.drawer-footer-top { display: flex; justify-content: space-between; gap: 12px; align-items: center; }
.drawer-logout {
  min-height: 32px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 14px;
  cursor: pointer;
}
.drawer-logout svg { width: 18px; height: 18px; color: #aebee5; }
.drawer-footer small { color: #aebee5; font-size: 10px; }
.drawer-emergency {
  min-height: 41px;
  border: 1px solid rgba(255, 255, 255, .54);
  border-radius: 999px;
  background: transparent;
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.drawer-emergency:hover { background: rgba(255, 255, 255, .08); }

@media (max-width: 420px) {
  .drawer-panel { width: 80vw; }
  .drawer-top { padding-top: 24px; }
}

