regras.b1.05:
.appointments-shell {
  width: 100%;
  display: grid;
  gap: 16px;
}

.appointments-head {
  padding: 2px 2px 0;
}

.appointments-eyebrow {
  display: block;
  margin-bottom: 6px;
  color: var(--gold);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.appointments-head h1 {
  margin: 0;
  color: var(--primary);
  font-size: 24px;
  line-height: 1.15;
  letter-spacing: -.025em;
}

.appointments-head p {
  max-width: 580px;
  margin: 8px 0 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.5;
}

.appointments-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 6px;
  padding: 5px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: #f8fafc;
}

.appointments-tabs button {
  min-width: 0;
  min-height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #667085;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}

.appointments-tabs button b {
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: #e9eef5;
  color: #475467;
  font-size: 10px;
}

.appointments-tabs button.is-active {
  background: #fff;
  color: var(--primary);
  box-shadow: 0 1px 4px rgba(16,35,63,.10);
}

.appointments-tabs button.is-active b {
  background: #fff5dd;
  color: #875b09;
}

.appointments-panels > section[hidden] {
  display: none !important;
}

.appointments-section-head {
  margin-bottom: 10px;
}

.appointments-section-head h2 {
  margin: 0;
  color: var(--primary);
  font-size: 17px;
}

.appointments-section-head p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 12px;
}

.appointments-list {
  display: grid;
  gap: 10px;
}

.appointment-card {
  width: 100%;
  display: grid;
  grid-template-columns: minmax(0,1fr) auto;
  gap: 12px;
  align-items: center;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: #fff;
  color: var(--text);
  text-align: left;
  cursor: pointer;
  box-shadow: 0 2px 7px rgba(16,35,63,.035);
}

.appointment-card:hover {
  border-color: #b9c7d9;
}

.appointment-main {
  min-width: 0;
}

.appointment-topline {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
}

.appointment-topline time {
  color: var(--muted);
  font-size: 10px;
}

.status {
  display: inline-flex;
  min-height: 23px;
  align-items: center;
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .035em;
  text-transform: uppercase;
}

.status-requested {
  background: #fff6df;
  color: #855b0b;
}

.status-ongoing {
  background: #ecfdf3;
  color: #087443;
}

.status-closed {
  background: #f2f4f7;
  color: #475467;
}

.appointment-card h3 {
  margin: 11px 0 0;
  color: var(--primary);
  font-size: 16px;
}

.appointment-card strong {
  display: block;
  margin-top: 4px;
  color: #344054;
  font-size: 12px;
}

.appointment-card p {
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.45;
}

.appointment-chevron {
  color: var(--gold);
  font-size: 26px;
  line-height: 1;
}

@media (max-width: 520px) {
  .appointments-tabs {
    grid-template-columns: 1fr;
  }

  .appointments-tabs button {
    justify-content: space-between;
    padding: 0 12px;
  }
}

@media (min-width: 720px) {
  .appointments-list {
    grid-template-columns: 1fr 1fr;
  }
}

