regras.b1.05:
.prototype-drawer {
  position: fixed;
  z-index: 40;
  inset: 0;
  display: none;
}

.prototype-drawer.open { display: block; }

.drawer-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  border: 0;
  background: rgba(7, 16, 30, .60);
}

.drawer-panel {
  position: absolute;
  inset: 0 auto 0 0;
  width: min(80vw, 360px);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background: #3b4a7d;
  color: #fff;
  box-shadow: 12px 0 30px rgba(0, 0, 0, .32);
}

.drawer-top {
  flex: 0 0 auto;
  min-height: 106px;
  padding: 30px 22px 20px;
  display: flex;
  align-items: center;
}

.drawer-identity {
  min-width: 0;
  display: flex;
  gap: 14px;
  align-items: center;
}

.drawer-avatar {
  flex: 0 0 56px;
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  border: 2px solid rgba(255, 255, 255, .20);
  border-radius: 50%;
  background: #dbeafe;
  color: #1e3a8a;
  font-size: 20px;
  font-weight: 800;
}

.drawer-profile { min-width: 0; }
.drawer-profile strong,
.drawer-profile small { display: block; }
.drawer-profile strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 16px;
  font-weight: 600;
}
.drawer-profile small {
  margin-top: 2px;
  color: #bfdbfe;
  font-size: 11px;
  font-weight: 400;
  text-transform: lowercase;
}

.drawer-online {
  flex: 0 0 auto;
  width: calc(100% - 44px);
  margin: 0 22px 10px;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  align-items: center;
  border: 1px solid rgba(255, 255, 255, .18);
  border-radius: 10px;
  padding: 10px 12px;
  background: rgba(255, 255, 255, .08);
  color: #fff;
  text-align: left;
  cursor: pointer;
}
.drawer-online-copy strong,
.drawer-online-copy small { display: block; }
.drawer-online-copy strong { font-size: 13px; }
.drawer-online-copy small { margin-top: 2px; color: #bfdbfe; font-size: 10px; }
.online-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #4ade80;
  box-shadow: 0 0 0 4px rgba(74, 222, 128, .14);
}
.drawer-online.is-offline .online-dot { background: #98a2b3; box-shadow: none; }
.online-switch { position: relative; width: 38px; height: 22px; border-radius: 999px; background: #22c55e; }
.online-switch b { position: absolute; top: 3px; right: 3px; width: 16px; height: 16px; border-radius: 50%; background: #fff; }
.drawer-online.is-offline .online-switch { background: #64748b; }
.drawer-online.is-offline .online-switch b { right: 19px; }

.drawer-nav {
  flex: 1 1 auto;
  min-height: 0;
  display: block;
  margin: 0;
  padding: 0 0 8px;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, .35) transparent;
}
.drawer-nav::-webkit-scrollbar { width: 5px; }
.drawer-nav::-webkit-scrollbar-thumb { border-radius: 999px; background: rgba(255, 255, 255, .35); }

.drawer-nav button {
  width: 100%;
  min-height: 51px;
  padding: 14px 22px;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, .10);
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 15px;
  align-items: center;
  text-align: left;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
}
.drawer-nav button:hover { background: rgba(255, 255, 255, .08); }
.drawer-icon { flex: 0 0 20px; width: 20px; height: 20px; color: #aebee5; }

.drawer-footer {
  flex: 0 0 auto;
  margin-top: 0;
  padding: 16px 22px 30px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  background: rgba(0, 0, 0, .10);
}
.drawer-footer-top { display: flex; justify-content: space-between; gap: 12px; align-items: center; }
.drawer-logout {
  min-height: 32px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 14px;
  cursor: pointer;
}
.drawer-logout svg { width: 18px; height: 18px; color: #aebee5; }
.drawer-footer small { color: #aebee5; font-size: 10px; }
.drawer-emergency {
  min-height: 41px;
  border: 1px solid rgba(255, 255, 255, .54);
  border-radius: 999px;
  background: transparent;
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.drawer-emergency:hover { background: rgba(255, 255, 255, .08); }

@media (max-width: 420px) {
  .drawer-panel { width: 80vw; }
  .drawer-top { padding-top: 24px; }
}

regras.b1.01:
/* Casca macro: posição e responsividade. Componentes cuidam do conteúdo interno. */
:root{--primary:#10233f;--primary-soft:#173c6b;--gold:#b88932;--page:#eef2f6;--surface:#fff;--line:#dbe3ee;--text:#172033;--muted:#667085;--main-max:720px;--main-padding-x:16px;--main-padding-top:22px;--main-padding-bottom:28px;--section-gap:12px;--nav-desktop-width:210px;font-family:"Plus Jakarta Sans","Segoe UI",Arial,sans-serif}
*{box-sizing:border-box}html,body{min-width:320px;min-height:100%;margin:0}body{min-height:100dvh;background:var(--page);color:var(--text);overflow-x:hidden}#screen-root,.screen-runtime{min-height:100dvh;background:var(--page)}screen-section{display:block;width:100%}.screen-slot{min-width:0;width:100%}
.screen-slot--header{position:sticky;top:0;z-index:30;background:var(--page)}.screen-slot--header>screen-section+screen-section{margin-top:0}
.screen-layout{min-height:calc(100dvh - 1px);display:block}.screen-slot--main{width:min(100%,var(--main-max));margin:0 auto;padding:var(--main-padding-top) var(--main-padding-x) calc(var(--main-padding-bottom) + 76px)}.screen-slot--main>screen-section+screen-section{margin-top:var(--section-gap)}
.screen-slot--navigation{position:fixed;z-index:20;right:0;bottom:0;left:0}.screen-slot--navigation:not([data-active="true"]){display:none}.screen-slot--menu,.screen-slot--modal,.screen-slot--popup,.screen-slot--alert{height:0;position:relative;z-index:40}.screen-slot--modal{z-index:50}.screen-slot--popup{z-index:60}.screen-slot--alert{z-index:70}
@media(min-width:900px){.screen-layout{display:grid;grid-template-columns:var(--nav-desktop-width) minmax(0,1fr);align-items:start}.screen-runtime:not([data-has-navigation="true"]) .screen-layout{grid-template-columns:minmax(0,1fr)}.screen-slot--navigation{position:sticky;top:0;right:auto;bottom:auto;left:auto;grid-column:1;grid-row:1;align-self:start;min-height:100%;padding-top:18px}.screen-slot--main{grid-column:2;grid-row:1;padding-bottom:var(--main-padding-bottom)}.screen-runtime:not([data-has-navigation="true"]) .screen-slot--main{grid-column:1}}
.screen-loading,.screen-error{width:min(100% - 32px,720px);margin:32px auto;padding:18px;border:1px solid var(--line);border-radius:14px;background:#fff;line-height:1.55}.screen-error h1{margin:0 0 8px;color:var(--primary);font-size:20px}.screen-error code{display:block;margin-top:12px;padding:10px;border-radius:8px;background:#eef2f6;overflow-wrap:anywhere}.section-runtime-warning{max-width:var(--main-max,720px);margin:12px auto;padding:12px 14px;border:1px dashed #b8c2cf;border-radius:12px;background:#fff;color:#334155;display:grid;gap:4px}

