.online-switch b {
  position:absolute;
  top:3px;
  right:3px;
  width:17px;
  height:17px;
  border-radius:50%;
  background:#fff;
}
.is-offline .online-switch { background:#98a2b3; }
.is-offline .online-switch b { right:20px; }

regras.b1.07:
