}
.op-hero h1 {
  margin: 0;
  font-size: 24px;
  line-height: 1.15;
}
.op-hero p {
  margin: 7px 0 0;
  color: #dce7f4;
  line-height: 1.5;
}
.op-card {
  margin-bottom: 12px;
  padding: 17px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: #fff;
}
.op-card h2, .op-card h3 {
  margin: 0;
  color: var(--primary);
}
.op-card h2 { font-size: 18px; }
.op-card h3 { font-size: 15px; }
.op-card p {
  margin: 7px 0 0;
