}
.is-offline .online-dot {
  background: #98a2b3;
  box-shadow: none;
}
.status-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
  border-radius: 999px;
  padding: 6px 9px;
  background: #edf3fa;
  color: var(--primary);
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
}
.status-chip.waiting { background: #fff4d9; color: #7a5400; }
.status-chip.ok { background: #e5f7ee; color: #08744e; }
.status-chip.danger { background: #feeceb; color: #b42318; }
.op-tabs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
  margin-bottom: 12px;
}
.op-tabs button {
  min-height: 42px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #fff;
  color: var(--muted);
  font-weight: 800;
  cursor: pointer;
}
.op-tabs button.active {
  border-color: var(--primary);
  background: var(--primary);
  color: #fff;
}
.meta-list {
  display: grid;
  gap: 8px;
  margin-top: 12px;
}
.meta-row {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding-top: 9px;
  border-top: 1px solid #edf0f4;
  font-size: 12px;
}
.meta-row span { color: var(--muted); }
.meta-row strong { color: var(--primary); text-align: right; }
.op-buttons {
  display: grid;
