.app-notifications-badge {
  position:absolute;
  top:4px;
  right:2px;
  min-width:16px;
  height:16px;
  padding:0 4px;
  display:grid;
  place-items:center;
  border:2px solid var(--primary);
  border-radius:999px;
  background:#ef4444;
  color:#fff;
  font-size:9px;
