regras.b1.05:
.profile-shell {
  width: 100%;
  display: grid;
  gap: 16px;
}

.profile-heading {
  display: grid;
  grid-template-columns: auto minmax(0,1fr);
  gap: 13px;
  align-items: center;
}

.profile-avatar {
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  border-radius: 18px;
  background: var(--primary);
  color: #fff;
  font-size: 17px;
  font-weight: 900;
  letter-spacing: .03em;
}

.profile-eyebrow {
  display: block;
  margin-bottom: 4px;
  color: var(--gold);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.profile-heading h1 {
  margin: 0;
  color: var(--primary);
  font-size: 23px;
  line-height: 1.1;
  letter-spacing: -.025em;
}

.profile-heading p {
  max-width: 620px;
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}

.profile-tabs {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 6px;
  padding: 5px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: #f8fafc;
}

.profile-tabs button {
