  gap: 6px;
  min-width: 0;
}

.field span {
  color: #344054;
  font-size: 11px;
  font-weight: 800;
}

.field input,
.field select,
.field textarea {
  width: 100%;
  min-width: 0;
  min-height: 44px;
  padding: 10px 11px;
  border: 1px solid #d0d5dd;
  border-radius: 10px;
  background: #fff;
  color: var(--text);
  font: inherit;
  font-size: 13px;
  outline: none;
  box-sizing: border-box;
}

.field textarea {
