  background: var(--line);
}

.check-grid {
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 8px;
}

.check-option {
  min-height: 42px;
  display: flex;
  gap: 9px;
  align-items: center;
  padding: 9px 10px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #fafbfc;
  color: #344054;
  font-size: 12px;
  cursor: pointer;
}

.check-option input {
  width: 17px;
  height: 17px;
  accent-color: var(--primary);
}

.profile-note {
  display: grid;
  gap: 4px;
  padding: 12px 13px;
  border: 1px solid #e6d7aa;
  border-radius: 12px;
  background: #fffaf0;
}

.profile-note strong {
  color: #76520d;
  font-size: 12px;
}

.profile-note span {
  color: #725c31;
  font-size: 11px;
  line-height: 1.45;
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  padding-top: 2px;
}

.primary-button {
  min-height: 44px;
  padding: 0 18px;
  border: 0;
  border-radius: 11px;
  background: var(--primary);
  color: #fff;
  font-weight: 800;
  cursor: pointer;
}

.profile-toast {
  padding: 11px 13px;
  border-radius: 11px;
  background: #ecfdf3;
  color: #087443;
  font-size: 12px;
  font-weight: 800;
  text-align: center;
}

.profile-toast[hidden] {
  display: none !important;
}

@media (max-width: 620px) {
  .field-grid.two,
  .field-grid.three,
  .check-grid {
    grid-template-columns: 1fr;
  }

  .profile-tabs {
    grid-template-columns: 1fr;
  }

  .profile-heading {
    align-items: start;
  }
}

