  padding: 12px 14px;
  font-weight: 800;
  cursor: pointer;
}
.op-secondary {
  border: 1px solid var(--line);
  background: #fff;
  color: var(--primary);
}
.op-danger {
  border: 1px solid #f1b6b2;
  background: #fff5f4;
  color: #b42318;
}
.op-empty {
  padding: 28px 16px;
  border: 1px dashed #cbd5e1;
  border-radius: 14px;
  background: #f8fafc;
  color: var(--muted);
  text-align: center;
  font-size: 13px;
}
.op-form {
  display: grid;
  gap: 12px;
}
.op-form label {
  display: grid;
  gap: 6px;
  color: var(--primary);
  font-size: 11px;
  font-weight: 800;
}
.op-form input, .op-form select, .op-form textarea {
  width: 100%;
  min-height: 48px;
  border: 1px solid var(--line);
  border-radius: 11px;
  padding: 11px 12px;
  background: #fff;
  color: var(--text);
  font: inherit;
}
.op-form textarea { min-height: 110px; resize: vertical; }
.switch-row {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: center;
  padding: 13px 0;
  border-bottom: 1px solid #edf0f4;
}
.switch-row:last-child { border-bottom: 0; }
.switch-row strong, .switch-row small { display: block; }
.switch-row small { margin-top: 3px; color: var(--muted); font-size: 11px; }
.prototype-switch {
  position: relative;
  width: 46px;
  height: 26px;
  flex: 0 0 auto;
  border: 0;
  border-radius: 999px;
  background: #15945e;
  cursor: pointer;
}
.prototype-switch::after {
  position: absolute;
  top: 3px;
  right: 3px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #fff;
  content: "";
  box-shadow: 0 2px 5px rgba(0,0,0,.18);
}
.prototype-switch.is-offline { background: #cbd5e1; }
.prototype-switch.is-offline::after { right: 23px; }
.day-list {
  display: grid;
  gap: 7px;
}
.day-list label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 49px;
  border: 1px solid var(--line);
  border-radius: 11px;
  padding: 10px 12px;
  background: #fff;
  color: var(--primary);
  font-weight: 800;
}
.day-list input { width: 19px; height: 19px; accent-color: var(--primary); }
.radius-value {
  margin: 4px 0 14px;
  color: var(--primary);
  text-align: center;
  font-size: 38px;
  font-weight: 900;
}
.radius-value small { font-size: 14px; color: var(--muted); }
.profile-head {
  display: flex;
  gap: 13px;
  align-items: center;
}
.profile-avatar {
  width: 58px;
  height: 58px;
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 18px;
  background: #dfe8f3;
  color: var(--primary);
  font-weight: 900;
}
.bottom-nav {
  position: fixed;
  z-index: 10;
  right: 0;
  bottom: 0;
  left: 0;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  border-top: 1px solid var(--line);
  background: rgba(255,255,255,.97);
  backdrop-filter: blur(12px);
}
.bottom-nav button {
  min-height: 64px;
  border: 0;
  padding: 7px 3px;
  background: transparent;
  color: #778195;
  font-size: 9px;
  font-weight: 800;
  cursor: pointer;
}
.bottom-nav button.active {
  color: var(--primary);
  background: #f0f5fb;
}
.prototype-drawer {
  position: fixed;
  z-index: 40;
  inset: 0;
  display: none;
}
.prototype-drawer.open { display: block; }
.drawer-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  border: 0;
  background: rgba(7,16,30,.55);
}
.drawer-panel {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: min(88vw, 360px);
  overflow: auto;
  padding: 18px 14px 22px;
  background: linear-gradient(180deg, #10233f, #0a1b32);
  color: #fff;
  box-shadow: 12px 0 28px rgba(0,0,0,.28);
}
.drawer-top {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: flex-start;
  padding: 8px 5px 18px;
}
.drawer-identity {
  display: flex;
  gap: 11px;
  align-items: center;
}
.drawer-identity strong, .drawer-identity small { display: block; }
.drawer-identity small {
  margin-top: 3px;
  color: #aebdd0;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .08em;
}
.drawer-avatar {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border: 1px solid #ffffff33;
  border-radius: 50%;
  background: #ffffff14;
  font-weight: 900;
}
.drawer-close {
  border: 0;
  background: transparent;
  color: #fff;
  font-size: 30px;
  line-height: 1;
  cursor: pointer;
}
.drawer-online {
  width: 100%;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  align-items: center;
  border: 1px solid #ffffff1f;
  border-radius: 13px;
  padding: 12px;
  background: #ffffff0d;
  color: #fff;
  text-align: left;
  cursor: pointer;
}
.drawer-online strong, .drawer-online small { display: block; }
.drawer-online small { margin-top: 2px; color: #aebdd0; font-size: 10px; }
.online-switch {
  position: relative;
  width: 42px;
  height: 24px;
  border-radius: 999px;
  background: #15945e;
}
.online-switch b {
  position: absolute;
  top: 3px;
  right: 3px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #fff;
}
.drawer-online.is-offline .online-switch { background: #64748b; }
.drawer-online.is-offline .online-switch b { right: 21px; }
.drawer-nav {
  display: grid;
  gap: 3px;
  margin-top: 12px;
}
.drawer-nav button, .drawer-footer button {
  min-height: 44px;
  border: 0;
  border-radius: 10px;
  padding: 10px 12px;
  background: transparent;
  color: #f8fafc;
  text-align: left;
  font-weight: 700;
  cursor: pointer;
}
.drawer-nav button:hover, .drawer-footer button:hover { background: #ffffff10; }
.drawer-footer {
  margin-top: 16px;
  padding-top: 12px;
  border-top: 1px solid #ffffff1a;
}
.drawer-footer small {
  display: block;
  padding: 8px 12px 0;
  color: #8190a5;
}
.op-toast {
  position: fixed;
  z-index: 50;
  left: 50%;
  bottom: 82px;
  max-width: calc(100vw - 32px);
  transform: translate(-50%, 16px);
  border-radius: 999px;
  padding: 10px 14px;
  background: #111827;
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  opacity: 0;
  pointer-events: none;
  transition: .2s ease;
}
.op-toast.show { opacity: 1; transform: translate(-50%, 0); }
.is-operational .open-index { bottom: 82px; }

@media (min-width: 720px) {
  .op-shell { padding: 28px 22px 52px; }
  .op-grid.two { grid-template-columns: 1fr 1fr; }
  .bottom-nav {
    left: 50%;
    width: min(720px, 100%);
    transform: translateX(-50%);
    border-right: 1px solid var(--line);
    border-left: 1px solid var(--line);
    border-radius: 16px 16px 0 0;
    overflow: hidden;
  }
}




