  margin-top: 14px;
}
.op-buttons.inline {
  grid-template-columns: 1fr 1fr;
}
.op-secondary, .op-danger {
  min-height: 48px;
  border-radius: 12px;
  padding: 12px 14px;
  font-weight: 800;
  cursor: pointer;
}
.op-secondary {
  border: 1px solid var(--line);
  background: #fff;
  color: var(--primary);
}
.op-danger {
  border: 1px solid #f1b6b2;
  background: #fff5f4;
  color: #b42318;
}
.op-empty {
  padding: 28px 16px;
  border: 1px dashed #cbd5e1;
  border-radius: 14px;
  background: #f8fafc;
  color: var(--muted);
  text-align: center;
  font-size: 13px;
}
.op-form {
  display: grid;
  gap: 12px;
}
.op-form label {
  display: grid;
  gap: 6px;
  color: var(--primary);
  font-size: 11px;
  font-weight: 800;
}
.op-form input, .op-form select, .op-form textarea {
  width: 100%;
  min-height: 48px;
  border: 1px solid var(--line);
  border-radius: 11px;
  padding: 11px 12px;
  background: #fff;
  color: var(--text);
  font: inherit;
}
.op-form textarea { min-height: 110px; resize: vertical; }
.switch-row {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: center;
  padding: 13px 0;
  border-bottom: 1px solid #edf0f4;
}
.switch-row:last-child { border-bottom: 0; }
.switch-row strong, .switch-row small { display: block; }
.switch-row small { margin-top: 3px; color: var(--muted); font-size: 11px; }
.prototype-switch {
  position: relative;
