regras.b1.06:
.prototype-drawer {
  position: fixed;
  z-index: 40;
  inset: 0;
  display: none;
}

.prototype-drawer.open { display: block; }

.drawer-backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  border: 0;
  background: rgba(7, 16, 30, .60);
}

.drawer-panel {
  position: absolute;
  inset: 0 auto 0 0;
  width: min(80vw, 360px);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background: #3b4a7d;
  color: #fff;
  box-shadow: 12px 0 30px rgba(0, 0, 0, .32);
}

.drawer-top {
  flex: 0 0 auto;
  min-height: 106px;
  padding: 30px 22px 20px;
  display: flex;
  align-items: center;
}

.drawer-identity {
  min-width: 0;
  display: flex;
  gap: 14px;
  align-items: center;
}

.drawer-avatar {
  flex: 0 0 56px;
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  border: 2px solid rgba(255, 255, 255, .20);
  border-radius: 50%;
  background: #dbeafe;
  color: #1e3a8a;
  font-size: 20px;
  font-weight: 800;
}

.drawer-profile { min-width: 0; }
.drawer-profile strong,
.drawer-profile small { display: block; }
.drawer-profile strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 16px;
  font-weight: 600;
}
.drawer-profile small {
  margin-top: 2px;
  color: #bfdbfe;
  font-size: 11px;
  font-weight: 400;
  text-transform: lowercase;
}

.drawer-online {
  flex: 0 0 auto;
  width: calc(100% - 44px);
  margin: 0 22px 10px;
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 10px;
  align-items: center;
  border: 1px solid rgba(255, 255, 255, .18);
  border-radius: 10px;
  padding: 10px 12px;
  background: rgba(255, 255, 255, .08);
  color: #fff;
  text-align: left;
  cursor: pointer;
}
.drawer-online-copy strong,
.drawer-online-copy small { display: block; }
.drawer-online-copy strong { font-size: 13px; }
.drawer-online-copy small { margin-top: 2px; color: #bfdbfe; font-size: 10px; }
.online-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #4ade80;
  box-shadow: 0 0 0 4px rgba(74, 222, 128, .14);
}
.drawer-online.is-offline .online-dot { background: #98a2b3; box-shadow: none; }
.online-switch { position: relative; width: 38px; height: 22px; border-radius: 999px; background: #22c55e; }
.online-switch b { position: absolute; top: 3px; right: 3px; width: 16px; height: 16px; border-radius: 50%; background: #fff; }
.drawer-online.is-offline .online-switch { background: #64748b; }
.drawer-online.is-offline .online-switch b { right: 19px; }

.drawer-nav {
  flex: 1 1 auto;
  min-height: 0;
  display: block;
  margin: 0;
  padding: 0 0 8px;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, .35) transparent;
}
.drawer-nav::-webkit-scrollbar { width: 5px; }
.drawer-nav::-webkit-scrollbar-thumb { border-radius: 999px; background: rgba(255, 255, 255, .35); }

.drawer-nav button {
  width: 100%;
  min-height: 51px;
  padding: 14px 22px;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, .10);
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 15px;
  align-items: center;
  text-align: left;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
}
.drawer-nav button:hover { background: rgba(255, 255, 255, .08); }
.drawer-icon { flex: 0 0 20px; width: 20px; height: 20px; color: #aebee5; }

.drawer-footer {
  flex: 0 0 auto;
  margin-top: 0;
  padding: 16px 22px 30px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  background: rgba(0, 0, 0, .10);
}
.drawer-footer-top { display: flex; justify-content: space-between; gap: 12px; align-items: center; }
.drawer-logout {
  min-height: 32px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #f8fafc;
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 14px;
  cursor: pointer;
}
.drawer-logout svg { width: 18px; height: 18px; color: #aebee5; }
.drawer-footer small { color: #aebee5; font-size: 10px; }
.drawer-emergency {
  min-height: 41px;
  border: 1px solid rgba(255, 255, 255, .54);
  border-radius: 999px;
  background: transparent;
  color: #fff;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.drawer-emergency:hover { background: rgba(255, 255, 255, .08); }

@media (max-width: 420px) {
  .drawer-panel { width: 80vw; }
  .drawer-top { padding-top: 24px; }
}

regras.b1.01:
/* Base visual original incorporada ao pacote autocontido. */
/* ===== app.css ===== */
:root {
  --primary: #10233f;
  --primary-soft: #173c6b;
  --gold: #b88932;
  --page: #eef2f6;
  --surface: #fff;
  --line: #dbe3ee;
  --text: #172033;
  --muted: #667085;
  font-family: "Plus Jakarta Sans", "Segoe UI", Arial, sans-serif;
}
* {
  box-sizing: border-box;
}
body {
  min-width: 320px;
  min-height: 100dvh;
  margin: 0;
  background: var(--page);
  color: var(--text);
}
a {
  color: inherit;
  text-decoration: none;
}
button,
input {
  font: inherit;
}
.screen {
  display: none;
  width: 100%;
  min-height: 100dvh;
}
.screen.active {
  display: block;
  animation: fade 0.28s ease;
}
@keyframes fade {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.open-index {
  position: fixed;
  z-index: 20;
  right: 18px;
  bottom: 18px;
  border: 0;
  border-radius: 999px;
  padding: 10px 14px;
  background: rgba(17, 24, 39, 0.82);
  color: #fff;
  font-weight: 800;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.25);
  cursor: pointer;
}
.open-index span {
  display: inline-grid;
  min-width: 18px;
  place-items: center;
  border-radius: 50%;
  background: #fff;
  color: var(--primary);
  font-size: 11px;
}
.sheet {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: none;
}
.sheet.open {
  display: block;
}
.sheet-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(15, 23, 42, 0.5);
}
.sheet-panel {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  max-height: 72dvh;
  overflow: auto;
  border-radius: 20px 20px 0 0;
  background: #fff;
  box-shadow: 0 -12px 30px rgba(0, 0, 0, 0.2);
}
.sheet-head {
  position: sticky;
  top: 0;
  display: flex;
  justify-content: space-between;
  padding: 16px 18px;
  border-bottom: 1px solid var(--line);
  background: #fff;
}
.sheet-head button {
  border: 0;
  background: transparent;
  color: var(--primary);
  font-weight: 800;
  cursor: pointer;
}
.screen-link {
  display: flex;
  width: 100%;
  gap: 12px;
  align-items: center;
  border: 0;
  border-bottom: 1px solid var(--line);
  padding: 15px 18px;
  background: #fff;
  text-align: left;
  color: var(--text);
