  width: 76px;
  height: 76px;
  margin: auto;
  place-items: center;
  border-radius: 24px;
  background: var(--primary);
  box-shadow: 0 10px 22px rgba(0, 0, 0, 0.18);
}
.mark img {
  width: 54%;
