/* Casca macro: posição e responsividade. Componentes cuidam do conteúdo interno. */
:root{--primary:#10233f;--primary-soft:#173c6b;--gold:#b88932;--page:#eef2f6;--surface:#fff;--line:#dbe3ee;--text:#172033;--muted:#667085;--main-max:720px;--main-padding-x:16px;--main-padding-top:22px;--main-padding-bottom:28px;--section-gap:12px;--nav-desktop-width:210px;font-family:"Plus Jakarta Sans","Segoe UI",Arial,sans-serif}
*{box-sizing:border-box}html,body{min-width:320px;min-height:100%;margin:0}body{min-height:100dvh;background:var(--page);color:var(--text);overflow-x:hidden}#screen-root,.screen-runtime{min-height:100dvh;background:var(--page)}screen-section{display:block;width:100%}.screen-slot{min-width:0;width:100%}
.screen-slot--header{position:sticky;top:0;z-index:30;background:var(--page)}.screen-slot--header>screen-section+screen-section{margin-top:0}
.screen-layout{min-height:calc(100dvh - 1px);display:block}.screen-slot--main{width:min(100%,var(--main-max));margin:0 auto;padding:var(--main-padding-top) var(--main-padding-x) calc(var(--main-padding-bottom) + 76px)}.screen-slot--main>screen-section+screen-section{margin-top:var(--section-gap)}
.screen-slot--navigation{position:fixed;z-index:20;right:0;bottom:0;left:0}.screen-slot--navigation:not([data-active="true"]){display:none}.screen-slot--menu,.screen-slot--modal,.screen-slot--popup,.screen-slot--alert{height:0;position:relative;z-index:40}.screen-slot--modal{z-index:50}.screen-slot--popup{z-index:60}.screen-slot--alert{z-index:70}
@media(min-width:900px){.screen-layout{display:grid;grid-template-columns:var(--nav-desktop-width) minmax(0,1fr);align-items:start}.screen-runtime:not([data-has-navigation="true"]) .screen-layout{grid-template-columns:minmax(0,1fr)}.screen-slot--navigation{position:sticky;top:0;right:auto;bottom:auto;left:auto;grid-column:1;grid-row:1;align-self:start;min-height:100%;padding-top:18px}.screen-slot--main{grid-column:2;grid-row:1;padding-bottom:var(--main-padding-bottom)}.screen-runtime:not([data-has-navigation="true"]) .screen-slot--main{grid-column:1}}
.screen-loading,.screen-error{width:min(100% - 32px,720px);margin:32px auto;padding:18px;border:1px solid var(--line);border-radius:14px;background:#fff;line-height:1.55}.screen-error h1{margin:0 0 8px;color:var(--primary);font-size:20px}.screen-error code{display:block;margin-top:12px;padding:10px;border-radius:8px;background:#eef2f6;overflow-wrap:anywhere}.section-runtime-warning{max-width:var(--main-max,720px);margin:12px auto;padding:12px 14px;border:1px dashed #b8c2cf;border-radius:12px;background:#fff;color:#334155;display:grid;gap:4px}

