    #08172d 100%
  );
}
.splash > div {
  text-align: center;
}
.splash button {
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  text-align: center;
}
.splash h1 {
  margin: 22px 0 0;
