}
.login__brand .mark {
  width: 64px;
  height: 64px;
  margin: 0 auto 16px;
  border-radius: 21px;
}
.login h1 {
  margin: 0;
  color: var(--primary);
  font-size: 27px;
}
.login__brand p {
  margin: 8px 0 0;
  color: var(--muted);
  font-size: 14px;
}
.card {
