.professional-onboarding .registration__shell { width: min(100%, 680px); }
.form-card textarea { width:100%; min-height:118px; resize:vertical; border:1px solid var(--line); border-radius:12px; padding:24px 14px 12px; background:#fff; color:var(--text); font:inherit; line-height:1.5; outline:0; }
.textarea-field { position:relative; margin-bottom:14px; }
.textarea-field label { position:absolute; z-index:1; top:8px; left:14px; color:var(--primary); font-size:10px; font-weight:800; pointer-events:none; }
.toggle-grid { display:grid; gap:10px; margin:0 0 14px; }
.toggle-card { display:grid; grid-template-columns:1fr auto; gap:14px; align-items:center; min-height:72px; border:1px solid var(--line); border-radius:14px; padding:14px; background:#fff; }
.toggle-card strong,.toggle-card small{display:block}.toggle-card small{margin-top:4px;color:var(--muted);line-height:1.4}.toggle-card input{width:20px;height:20px;accent-color:var(--primary)}
