.multi-select__label{position:absolute;z-index:1;top:8px;left:14px;color:var(--primary);font-size:10px;font-weight:800;pointer-events:none}.multi-select__value{display:block;overflow:hidden;color:var(--text);text-overflow:ellipsis;white-space:nowrap}.multi-select__panel{display:grid;gap:0;max-height:300px;overflow:auto;margin-top:7px;border:1px solid var(--line);border-radius:12px;background:#fff;box-shadow:0 12px 28px rgba(16,35,63,.14)}.multi-select__option{display:grid;grid-template-columns:auto 1fr;gap:10px;align-items:center;min-height:46px;padding:10px 13px;border-bottom:1px solid #edf1f5;cursor:pointer}.multi-select__option:last-child{border-bottom:0}.multi-select__option:hover{background:#f7f9fc}.multi-select__option input{width:18px;height:18px;accent-color:var(--primary)}
.inline-note{margin:0 0 14px;padding:12px 14px;border-left:3px solid var(--gold);border-radius:10px;background:#fff8e7;color:#614617;font-size:12px;line-height:1.5}.office-card[hidden],.review-section[data-office-review][hidden]{display:none}.status-pill{display:inline-flex;align-items:center;min-height:28px;margin-top:10px;border-radius:999px;padding:5px 10px;background:#edf4ff;color:var(--primary);font-size:11px;font-weight:800}
