  box-shadow:12px 0 30px rgba(0,0,0,.32)
}
.prototype-drawer.drawer-v3 .drawer-top{flex:0 0 auto;min-height:106px;padding:30px 22px 20px;align-items:center}
.prototype-drawer.drawer-v3 .drawer-identity{gap:14px;min-width:0;align-items:center}
.prototype-drawer.drawer-v3 .drawer-avatar{
  flex:0 0 56px;width:56px;height:56px;border:2px solid rgba(255,255,255,.2);
  background:#dbeafe;color:#1e3a8a;font-size:20px;font-weight:800
}
.prototype-drawer.drawer-v3 .drawer-profile{min-width:0}
.prototype-drawer.drawer-v3 .drawer-profile strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:16px;font-weight:600}
.prototype-drawer.drawer-v3 .drawer-profile small{margin-top:2px;color:#bfdbfe;font-size:11px;font-weight:400;letter-spacing:0;text-transform:lowercase}
.prototype-drawer.drawer-v3 .drawer-online{
