  border-bottom:1px solid rgba(255,255,255,.07);border-radius:0;background:rgba(0,0,0,.04);color:#fff;
  display:grid;grid-template-columns:auto 1fr auto;gap:11px;align-items:center;text-align:left;cursor:pointer
}
.prototype-drawer.drawer-v3 .drawer-online:hover{background:rgba(255,255,255,.07)}
.prototype-drawer.drawer-v3 .online-dot{width:9px;height:9px;border-radius:50%;background:#4ade80;box-shadow:0 0 0 3px rgba(74,222,128,.14)}
.prototype-drawer.drawer-v3 .is-offline .online-dot,.prototype-drawer.drawer-v3 .drawer-online.is-offline .online-dot{background:#94a3b8;box-shadow:none}
.prototype-drawer.drawer-v3 .drawer-online-copy strong,.prototype-drawer.drawer-v3 .drawer-online-copy small{display:block}
.prototype-drawer.drawer-v3 .drawer-online-copy strong{font-size:13px;font-weight:600}
.prototype-drawer.drawer-v3 .drawer-online-copy small{margin-top:1px;color:#bfdbfe;font-size:9px}
.prototype-drawer.drawer-v3 .online-switch{width:34px;height:19px;padding:2px;border-radius:999px;background:#60a5fa}
.prototype-drawer.drawer-v3 .online-switch b{display:block;width:15px;height:15px;margin-left:15px;border-radius:50%;background:#fff;transition:.2s}
.prototype-drawer.drawer-v3 .drawer-online.is-offline .online-switch{background:#64748b}
.prototype-drawer.drawer-v3 .drawer-online.is-offline .online-switch b{margin-left:0}
.prototype-drawer.drawer-v3 .drawer-nav{
