}
.app-role {
  font-size: 10px;
  font-weight: 800;
  opacity: .8;
  text-transform: uppercase;
  letter-spacing: .06em;
}
.app-titlebar {
  padding: 10px 18px;
  border-bottom: 1px solid var(--line);
  background: #fff;
  color: var(--primary);
  font-size: 13px;
}
.op-shell {
  width: min(100%, 720px);
  margin: 0 auto;
  padding: 22px 16px 36px;
}
.op-shell > .eyebrow {
  margin: 0 0 7px;
}
.op-intro {
  margin: 0 0 18px;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.55;
}
.op-hero {
  margin-bottom: 14px;
  padding: 19px;
  border-radius: 18px;
  background: linear-gradient(135deg, var(--primary), var(--primary-soft));
