}
.text-action {
  margin-top: 12px;
  border: 0;
  background: transparent;
  color: var(--primary);
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}
@media (min-width: 520px) {
  .field-grid {
    grid-template-columns: 1fr 1fr;
    gap: 12px;
  }
}
@media (min-width: 700px) {
  .registration__shell {
    padding-top: 38px;
    padding-bottom: 64px;
  }
  .form-card {
    padding: 26px;
    box-shadow: 0 12px 36px rgba(16, 35, 63, 0.10);
  }
}


