}
.op-hero h1 {
  margin: 0;
  font-size: 24px;
  line-height: 1.15;
}
.op-hero p {
  margin: 7px 0 0;
  color: #dce7f4;
  line-height: 1.5;
}
.op-card {
  margin-bottom: 12px;
  padding: 17px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: #fff;
}
.op-card h2, .op-card h3 {
  margin: 0;
  color: var(--primary);
}
.op-card h2 { font-size: 18px; }
.op-card h3 { font-size: 15px; }
.op-card p {
  margin: 7px 0 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}
.op-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 10px;
}
.op-action {
  width: 100%;
  min-height: 78px;
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 15px;
  padding: 14px 15px;
  background: #fff;
  color: var(--text);
  text-align: left;
  cursor: pointer;
}
.op-action strong, .op-action small { display: block; }
.op-action strong { color: var(--primary); font-size: 14px; }
.op-action small { margin-top: 4px; color: var(--muted); line-height: 1.35; }
.op-action::after {
