.app-header {
  min-height: 62px; display: grid; grid-template-columns: 42px 1fr auto; gap: 10px;
  align-items: center; padding: 8px 14px; background: var(--primary); color: #fff;
  box-shadow: 0 4px 14px rgba(16,35,63,.18);
}
.app-menu-button { width:40px;height:40px;display:grid;place-content:center;gap:4px;border:0;border-radius:10px;background:transparent;color:#fff;cursor:pointer; }
.app-menu-button span { width:20px;height:2px;border-radius:9px;background:currentColor; }
.app-brand { min-width:0;display:flex;align-items:center;gap:8px;font-size:16px;letter-spacing:-.02em; }
.app-brand img { width:27px;height:27px;object-fit:contain;filter:brightness(0) invert(1); }
.app-role { font-size:10px;font-weight:800;opacity:.8;text-transform:uppercase;letter-spacing:.06em; }
.app-notification-button{position:relative;width:40px;height:40px;display:grid;place-items:center;padding:0;border:0;border-radius:10px;background:transparent;color:#fff;cursor:pointer}.app-notification-button:hover{background:rgba(255,255,255,.09)}.app-notification-button svg{width:22px;height:22px}.app-notification-badge{position:absolute;right:2px;top:2px;min-width:17px;height:17px;display:grid;place-items:center;padding:0 4px;border:2px solid var(--primary);border-radius:999px;background:#d92d20;color:#fff;font-size:9px;font-weight:900;line-height:1}

regras.b1.04:
:host {
  display: block;
  width: 100%;
  color: var(--text, #172033);
  font-family: "Plus Jakarta Sans", "Segoe UI", Arial, sans-serif;
}
*, *::before, *::after { box-sizing: border-box; }
button, input, select, textarea { font: inherit; }
button { -webkit-tap-highlight-color: transparent; }
a { color: inherit; text-decoration: none; }
[hidden] { display: none !important; }


/* ===== app.css ===== */
:root {
  --primary: #10233f;
  --primary-soft: #173c6b;
  --gold: #b88932;
  --page: #eef2f6;
  --surface: #fff;
  --line: #dbe3ee;
  --text: #172033;
  --muted: #667085;
  font-family: "Plus Jakarta Sans", "Segoe UI", Arial, sans-serif;
}
* {
  box-sizing: border-box;
}
body {
  min-width: 320px;
  min-height: 100dvh;
  margin: 0;
  background: var(--page);
  color: var(--text);
}
a {
  color: inherit;
  text-decoration: none;
}
button,
input {
  font: inherit;
}
.screen {
  display: none;
  width: 100%;
  min-height: 100dvh;
}
.screen.active {
  display: block;
  animation: fade 0.28s ease;
}
@keyframes fade {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.open-index {
  position: fixed;
  z-index: 20;
  right: 18px;
  bottom: 18px;
  border: 0;
  border-radius: 999px;
  padding: 10px 14px;
  background: rgba(17, 24, 39, 0.82);
  color: #fff;
  font-weight: 800;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.25);
  cursor: pointer;
}
.open-index span {
  display: inline-grid;
  min-width: 18px;
  place-items: center;
  border-radius: 50%;
  background: #fff;
  color: var(--primary);
  font-size: 11px;
}
.sheet {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: none;
}
.sheet.open {
  display: block;
}
.sheet-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(15, 23, 42, 0.5);
}
.sheet-panel {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  max-height: 72dvh;
  overflow: auto;
  border-radius: 20px 20px 0 0;
  background: #fff;
  box-shadow: 0 -12px 30px rgba(0, 0, 0, 0.2);
}
.sheet-head {
  position: sticky;
  top: 0;
  display: flex;
  justify-content: space-between;
  padding: 16px 18px;
  border-bottom: 1px solid var(--line);
  background: #fff;
}
.sheet-head button {
  border: 0;
  background: transparent;
  color: var(--primary);
  font-weight: 800;
  cursor: pointer;
}
.screen-link {
  display: flex;
  width: 100%;
  gap: 12px;
  align-items: center;
  border: 0;
  border-bottom: 1px solid var(--line);
  padding: 15px 18px;
  background: #fff;
  text-align: left;
  color: var(--text);
  cursor: pointer;
}
.screen-link:hover {
  background: #f8fafc;
}
.screen-link .number {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border-radius: 50%;
  background: #e8eef5;
  color: var(--primary);
  font-size: 11px;
  font-weight: 900;
}
.screen-link.active {
  background: #eef5ff;
}
.mark {
  display: grid;
  width: 76px;
  height: 76px;
  margin: auto;
  place-items: center;
  border-radius: 24px;
  background: var(--primary);
  box-shadow: 0 10px 22px rgba(0, 0, 0, 0.18);
}
.mark img {
  width: 54%;
  height: 54%;
  object-fit: contain;
}
.splash {
  display: grid;
  width: 100%;
  min-height: 100dvh;
  padding: 28px;
  place-items: center;
  color: #fff;
  background: radial-gradient(
    circle at 50% 20%,
    #284e7d 0,
    var(--primary) 48%,
    #08172d 100%
  );
}
.splash > div {
  text-align: center;
}
.splash button {
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  text-align: center;
}
.splash h1 {
  margin: 22px 0 0;
  font-size: clamp(30px, 8vw, 46px);
  line-height: 1;
  letter-spacing: -0.04em;
}
.welcome {
  display: flex;
  flex-direction: column;
  background: var(--surface);
}
.welcome__image {
  min-height: 38dvh;
  overflow: hidden;
  background: #dce7f4;
}
.welcome__image img {
  display: block;
  width: 100%;
  min-height: 38dvh;
  height: 100%;
  object-fit: cover;
  object-position: top center;
}
.welcome__copy {
  display: flex;
  flex: 1;
  flex-direction: column;
  padding: 30px 24px 26px;
}
.eyebrow {
  margin: 0 0 10px;
  color: var(--gold);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}
.welcome h1 {
  margin: 0;
  color: var(--primary);
  font-size: clamp(28px, 7vw, 46px);
  line-height: 1.08;
  letter-spacing: -0.035em;
}
.welcome__copy > p:not(.eyebrow) {
  margin: 15px 0 26px;
  color: var(--muted);
  line-height: 1.6;
}
.grow {
  flex: 1;
}
.button {
  display: grid;
  width: 100%;
  min-height: 54px;
  place-items: center;
  border: 0;
  border-radius: 13px;
  padding: 14px 18px;
  background: var(--primary);
  color: #fff;
  font-size: 14px;
  font-weight: 800;
  cursor: pointer;
}
.login {
  min-height: 100dvh;
  background: var(--page);
}
.topbar {
  min-height: 64px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 18px;
  color: #fff;
  background: var(--primary);
  font-weight: 800;
}
.topbar img {
  width: 26px;
  height: 26px;
  object-fit: contain;
  filter: brightness(0) invert(1);
}
.login__shell {
  width: min(100%, 520px);
  margin: auto;
  padding: 28px 20px 48px;
}
.login__brand {
  margin: 8px 0 24px;
  text-align: center;
}
.login__brand .mark {
  width: 64px;
  height: 64px;
  margin: 0 auto 16px;
  border-radius: 21px;
}
.login h1 {
  margin: 0;
  color: var(--primary);
  font-size: 27px;
}
.login__brand p {
  margin: 8px 0 0;
  color: var(--muted);
  font-size: 14px;
}
.card {
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: #fff;
}
.field {
  position: relative;
  margin-bottom: 14px;
}
.field input {
  width: 100%;
  min-height: 57px;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 22px 14px 9px;
  outline: 0;
}
.field label {
  position: absolute;
  top: 8px;
  left: 14px;
  color: var(--primary);
  font-size: 10px;
  font-weight: 800;
}
.help {
  display: inline-block;
  margin: 2px 0 14px;
  color: var(--primary);
  font-size: 13px;
  font-weight: 800;
}
.divider {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 20px 0 12px;
  color: var(--muted);
  font-size: 12px;
}
.divider::before,
.divider::after {
  height: 1px;
  flex: 1;
  background: var(--line);
  content: "";
}
.secondary {
  width: 100%;
  min-height: 50px;
  margin-top: 9px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fff;
  color: var(--primary);
  font-weight: 800;
}
.signup {
  margin: 20px 0 0;
  color: var(--muted);
  text-align: center;
  font-size: 13px;
}
.signup a {
  color: var(--primary);
  font-weight: 800;
}
.status {
  min-height: 20px;
  margin: 12px 0 0;
  color: var(--primary);
  text-align: center;
  font-size: 12px;
  font-weight: 700;
}
@media (min-width: 700px) {
  .welcome {
    min-height: 100dvh;
    padding: 34px;
    background: #e9eff6;
  }
  .welcome__layout {
    width: min(1080px, 100%);
    min-height: min(680px, calc(100dvh - 68px));
    margin: auto;
    display: grid;
    grid-template-columns: 1.08fr 0.92fr;
    overflow: hidden;
    border: 1px solid var(--line);
    border-radius: 20px;
    background: #fff;
    box-shadow: 0 12px 36px rgba(16, 35, 63, 0.14);
  }
  .welcome__image,
  .welcome__image img {
    min-height: 0;
    height: 100%;
  }
  .welcome__copy {
    padding: clamp(42px, 6vw, 76px);
  }
  .login__shell {
    padding-top: 54px;
  }
  .card {
    padding: 28px;
    box-shadow: 0 12px 36px rgba(16, 35, 63, 0.14);
  }
}
.screen-link .number {
  width: auto;
  min-width: 46px;
  padding: 0 7px;
  border-radius: 999px;
}
.screen-meta {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}
.screen-meta strong {
  font-size: 14px;
}
.screen-meta small {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

/* ===== Cadastro comum — dados pessoais ===== */
.registration {
  min-height: 100dvh;
  background: var(--page);
}
.registration__shell {
  width: min(100%, 620px);
  margin: 0 auto;
  padding: 24px 18px 48px;
}
.registration__intro {
  margin: 2px 2px 18px;
}
.registration__intro h1,
.registration--success h1 {
  margin: 0;
  color: var(--primary);
  font-size: clamp(25px, 7vw, 34px);
  line-height: 1.12;
  letter-spacing: -0.025em;
}
.registration__intro > p:not(.eyebrow),
.registration--success > .registration__shell > p:not(.eyebrow):not(.form-status) {
  margin: 10px 0 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.58;
}
.progress {
  height: 5px;
  margin: 0 2px 18px;
  overflow: hidden;
  border-radius: 999px;
  background: #dce4ed;
}
.progress span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--gold);
}
.form-card {
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--surface);
}
.form-card .field:last-of-type {
  margin-bottom: 0;
}
.form-card .field input,
.form-card .select-field select {
  background: #fff;
  color: var(--text);
}
.select-field {
  position: relative;
  margin-bottom: 14px;
}
.select-field label {
  position: absolute;
  z-index: 1;
  top: 8px;
  left: 14px;
  color: var(--primary);
  font-size: 10px;
  font-weight: 800;
  pointer-events: none;
}
.select-field select {
  width: 100%;
  min-height: 57px;
  appearance: auto;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 22px 40px 9px 14px;
  outline: 0;
  cursor: pointer;
}
.field-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0;
}
.choice-group {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 0;
  border: 0;
}
.choice-group legend {
  margin-bottom: 10px;
  color: var(--primary);
  font-size: 12px;
  font-weight: 800;
}
.choice-card {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 12px;
  align-items: center;
  min-height: 78px;
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 14px;
  cursor: pointer;
  transition: border-color .18s ease, background .18s ease, box-shadow .18s ease;
}
.choice-card:has(input:checked) {
  border-color: var(--primary-soft);
  background: #f3f7fc;
  box-shadow: inset 0 0 0 1px rgba(23, 60, 107, .16);
}
.choice-card input {
  width: 18px;
  height: 18px;
  accent-color: var(--primary);
}
.choice-card span {
  min-width: 0;
}
.choice-card strong,
.choice-card small {
  display: block;
}
.choice-card strong {
  color: var(--primary);
  font-size: 14px;
}
.choice-card small {
  margin-top: 4px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}
.choice-card b {
  color: var(--primary-soft);
  font-size: 24px;
  font-weight: 500;
}
.form-note {
  display: flex;
  gap: 8px;
  margin: 16px 0 0;
  border-radius: 12px;
  padding: 12px 13px;
  background: #f3f6fa;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}
.form-note strong {
  flex: 0 0 auto;
  color: var(--primary);
}
.form-actions {
  display: grid;
  grid-template-columns: minmax(96px, .7fr) 1.3fr;
  gap: 10px;
  margin-top: 20px;
}
.form-actions.single {
  grid-template-columns: 1fr;
}
.secondary-action {
  min-height: 54px;
  border: 1px solid var(--line);
  border-radius: 13px;
  padding: 14px 16px;
  background: #fff;
  color: var(--primary);
  font-weight: 800;
  cursor: pointer;
}
.form-status {
  min-height: 18px;
  margin: 10px 0 0;
  color: #9b2c2c;
  text-align: center;
  font-size: 11px;
  font-weight: 700;
}
.upload-field {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px 12px;
  align-items: center;
  margin: 4px 0 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 13px 14px;
  cursor: pointer;
}
.upload-field input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.upload-field strong,
.upload-field small,
.upload-field em {
  display: block;
}
.upload-field strong {
  color: var(--primary);
  font-size: 13px;
}
.upload-field small,
.upload-field em {
  color: var(--muted);
  font-size: 10px;
  font-style: normal;
}
.upload-field em {
  grid-column: 1 / -1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.upload-button {
  border-radius: 9px;
  padding: 9px 10px;
  background: #eef3f8;
  color: var(--primary);
  font-size: 11px;
  font-weight: 800;
}
.legal-links {
  display: grid;
  gap: 8px;
  margin-bottom: 14px;
}
.legal-link {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 13px 14px;
  background: #fff;
  color: var(--primary);
  text-align: left;
  cursor: pointer;
}
.legal-link strong,
.legal-link small {
  display: block;
}
.legal-link small {
  margin-top: 3px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 500;
}
.legal-link b {
  font-size: 22px;
  font-weight: 500;
}
.check-row {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 10px;
  align-items: start;
  color: var(--text);
  font-size: 12px;
  line-height: 1.5;
  cursor: pointer;
}
.check-row input {
  width: 18px;
  height: 18px;
  margin: 1px 0 0;
  accent-color: var(--primary);
}
.link-button {
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--primary);
  font-weight: 800;
  cursor: pointer;
}
.review-section + .review-section {
  margin-top: 18px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
}
.review-section__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}
.review-section__head strong {
  color: var(--primary);
  font-size: 14px;
}
.review-section__head button {
  border: 0;
  padding: 5px 0;
  background: transparent;
  color: var(--primary-soft);
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}
.review-section dl {
  margin: 0;
}
.review-section dl > div {
  display: grid;
  grid-template-columns: minmax(92px, .55fr) 1.45fr;
  gap: 10px;
  padding: 8px 0;
}
.review-section dt {
  color: var(--muted);
  font-size: 11px;
}
.review-section dd {
  margin: 0;
  overflow-wrap: anywhere;
  color: var(--text);
  font-size: 12px;
  font-weight: 700;
}
.registration--success .success-shell {
  min-height: calc(100dvh - 64px);
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-top: 36px;
  padding-bottom: 60px;
  text-align: center;
}
.success-mark {
  display: grid;
  width: 74px;
  height: 74px;
  margin: 0 auto 18px;
  place-items: center;
  border-radius: 50%;
  background: var(--primary);
  color: #fff;
  font-size: 34px;
  font-weight: 800;
  box-shadow: 0 12px 28px rgba(16, 35, 63, .18);
}
.registration--success .form-note {
  margin: 24px 0 18px;
  text-align: left;
}
.text-action {
  margin-top: 12px;
  border: 0;
  background: transparent;
  color: var(--primary);
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}
@media (min-width: 520px) {
  .field-grid {
    grid-template-columns: 1fr 1fr;
    gap: 12px;
  }
}
@media (min-width: 700px) {
  .registration__shell {
    padding-top: 38px;
    padding-bottom: 64px;
  }
  .form-card {
    padding: 26px;
    box-shadow: 0 12px 36px rgba(16, 35, 63, 0.10);
  }
}


/* ===== onboarding-profissional.css ===== */
/* ===== Onboarding profissional ===== */
.professional-onboarding { min-height: 100dvh; background: var(--page); }
.professional-onboarding .registration__shell { width: min(100%, 680px); }
.form-card textarea { width:100%; min-height:118px; resize:vertical; border:1px solid var(--line); border-radius:12px; padding:24px 14px 12px; background:#fff; color:var(--text); font:inherit; line-height:1.5; outline:0; }
.textarea-field { position:relative; margin-bottom:14px; }
.textarea-field label { position:absolute; z-index:1; top:8px; left:14px; color:var(--primary); font-size:10px; font-weight:800; pointer-events:none; }
.toggle-grid { display:grid; gap:10px; margin:0 0 14px; }
.toggle-card { display:grid; grid-template-columns:1fr auto; gap:14px; align-items:center; min-height:72px; border:1px solid var(--line); border-radius:14px; padding:14px; background:#fff; }
.toggle-card strong,.toggle-card small{display:block}.toggle-card small{margin-top:4px;color:var(--muted);line-height:1.4}.toggle-card input{width:20px;height:20px;accent-color:var(--primary)}
.multi-select{position:relative;margin-bottom:14px}.multi-select summary{position:relative;min-height:62px;list-style:none;cursor:pointer;border:1px solid var(--line);border-radius:12px;padding:25px 42px 9px 14px;background:#fff;color:var(--text)}.multi-select summary::-webkit-details-marker{display:none}.multi-select summary::after{position:absolute;right:16px;top:50%;content:'▼';color:var(--primary);font-size:12px;transform:translateY(-50%);transition:transform .18s ease}.multi-select[open] summary::after{transform:translateY(-50%) rotate(180deg)}
.multi-select__label{position:absolute;z-index:1;top:8px;left:14px;color:var(--primary);font-size:10px;font-weight:800;pointer-events:none}.multi-select__value{display:block;overflow:hidden;color:var(--text);text-overflow:ellipsis;white-space:nowrap}.multi-select__panel{display:grid;gap:0;max-height:300px;overflow:auto;margin-top:7px;border:1px solid var(--line);border-radius:12px;background:#fff;box-shadow:0 12px 28px rgba(16,35,63,.14)}.multi-select__option{display:grid;grid-template-columns:auto 1fr;gap:10px;align-items:center;min-height:46px;padding:10px 13px;border-bottom:1px solid #edf1f5;cursor:pointer}.multi-select__option:last-child{border-bottom:0}.multi-select__option:hover{background:#f7f9fc}.multi-select__option input{width:18px;height:18px;accent-color:var(--primary)}
.inline-note{margin:0 0 14px;padding:12px 14px;border-left:3px solid var(--gold);border-radius:10px;background:#fff8e7;color:#614617;font-size:12px;line-height:1.5}.office-card[hidden],.review-section[data-office-review][hidden]{display:none}.status-pill{display:inline-flex;align-items:center;min-height:28px;margin-top:10px;border-radius:999px;padding:5px 10px;background:#edf4ff;color:var(--primary);font-size:11px;font-weight:800}
