/* ===== app.css ===== */
:root {
  --primary: #10233f;
  --primary-soft: #173c6b;
  --gold: #b88932;
  --page: #eef2f6;
  --surface: #fff;
  --line: #dbe3ee;
  --text: #172033;
  --muted: #667085;
  font-family: "Plus Jakarta Sans", "Segoe UI", Arial, sans-serif;
}
* {
  box-sizing: border-box;
}
body {
  min-width: 320px;
  min-height: 100dvh;
  margin: 0;
  background: var(--page);
  color: var(--text);
}
a {
  color: inherit;
  text-decoration: none;
}
button,
input {
  font: inherit;
}
.screen {
  display: none;
  width: 100%;
  min-height: 100dvh;
}
.screen.active {
  display: block;
  animation: fade 0.28s ease;
}
@keyframes fade {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.open-index {
  position: fixed;
  z-index: 20;
  right: 18px;
  bottom: 18px;
  border: 0;
  border-radius: 999px;
  padding: 10px 14px;
  background: rgba(17, 24, 39, 0.82);
  color: #fff;
  font-weight: 800;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.25);
  cursor: pointer;
}
.open-index span {
  display: inline-grid;
  min-width: 18px;
  place-items: center;
  border-radius: 50%;
  background: #fff;
  color: var(--primary);
  font-size: 11px;
}
.sheet {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: none;
}
.sheet.open {
  display: block;
}
.sheet-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(15, 23, 42, 0.5);
}
.sheet-panel {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  max-height: 72dvh;
  overflow: auto;
  border-radius: 20px 20px 0 0;
  background: #fff;
  box-shadow: 0 -12px 30px rgba(0, 0, 0, 0.2);
}
.sheet-head {
  position: sticky;
  top: 0;
  display: flex;
  justify-content: space-between;
  padding: 16px 18px;
  border-bottom: 1px solid var(--line);
  background: #fff;
}
.sheet-head button {
  border: 0;
  background: transparent;
  color: var(--primary);
  font-weight: 800;
  cursor: pointer;
}
.screen-link {
  display: flex;
  width: 100%;
  gap: 12px;
  align-items: center;
  border: 0;
  border-bottom: 1px solid var(--line);
  padding: 15px 18px;
  background: #fff;
  text-align: left;
  color: var(--text);
  cursor: pointer;
}
.screen-link:hover {
  background: #f8fafc;
}
.screen-link .number {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border-radius: 50%;
  background: #e8eef5;
  color: var(--primary);
  font-size: 11px;
  font-weight: 900;
}
.screen-link.active {
  background: #eef5ff;
}
.mark {
  display: grid;
  width: 76px;
  height: 76px;
  margin: auto;
  place-items: center;
  border-radius: 24px;
  background: var(--primary);
  box-shadow: 0 10px 22px rgba(0, 0, 0, 0.18);
}
.mark img {
  width: 54%;
  height: 54%;
  object-fit: contain;
}
.splash {
  display: grid;
  width: 100%;
  min-height: 100dvh;
  padding: 28px;
  place-items: center;
  color: #fff;
  background: radial-gradient(
    circle at 50% 20%,
    #284e7d 0,
    var(--primary) 48%,
    #08172d 100%
  );
}
.splash > div {
  text-align: center;
}
.splash button {
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  text-align: center;
}
.splash h1 {
  margin: 22px 0 0;
  font-size: clamp(30px, 8vw, 46px);
  line-height: 1;
  letter-spacing: -0.04em;
}
.welcome {
  display: flex;
  flex-direction: column;
  background: var(--surface);
}
.welcome__image {
  min-height: 38dvh;
  overflow: hidden;
  background: #dce7f4;
}
.welcome__image img {
  display: block;
  width: 100%;
