/* ===== operacao.css ===== */
/* Operação pós-Home — visual mobile-first do protótipo novo */
.operational {
  min-height: 100dvh;
  background: var(--page);
  padding-bottom: 78px;
}
.app-header {
  position: sticky;
  top: 0;
  z-index: 12;
  min-height: 62px;
  display: grid;
  grid-template-columns: 42px 1fr auto;
  gap: 10px;
  align-items: center;
  padding: 8px 14px;
